import{_ as e,o as a,c as s,a2 as n}from"./chunks/framework.hw3Av5Vn.js";const u=JSON.parse('{"title":"Building llamatron","description":"","frontmatter":{},"headers":[],"relativePath":"BUILDING_THE_BACKEND.md","filePath":"BUILDING_THE_BACKEND.md"}'),o={name:"BUILDING_THE_BACKEND.md"};function i(d,t,l,r,h,c){return a(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="building-llamatron" tabindex="-1">Building llamatron <a class="header-anchor" href="#building-llamatron" aria-label="Permalink to &quot;Building llamatron&quot;">​</a></h1><p>llamatron is written in Rust, a language that compiles to fast native code, so that many instruments can play at once with steady timing. It is built from its source on your computer by one script. No knowledge of Rust is needed: the script checks what building needs, offers to install whatever is missing, and installs nothing unless you say yes.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sh build.sh</span></span></code></pre></div><p><code>sh setup.sh</code> runs the same script at the end of setting up, so on a fresh copy of llamatron it is usually built already. After a <code>git pull</code>, run <code>sh build.sh</code> again to build the new code.</p><h2 id="what-building-needs" tabindex="-1">What Building Needs <a class="header-anchor" href="#what-building-needs" aria-label="Permalink to &quot;What Building Needs&quot;">​</a></h2><p>The script looks for each of these in turn and stops at the first that is missing, saying what to do.</p><table tabindex="0"><thead><tr><th>What</th><th>Why</th><th>How the script helps</th></tr></thead><tbody><tr><td>Apple&#39;s command line tools (Mac)</td><td>The compiler and linker every program on a Mac is built with.</td><td>Offers to start Apple&#39;s installer, <code>xcode-select --install</code>.</td></tr><tr><td>The ALSA headers and pkg-config (Linux)</td><td>The sound library llamatron plays through on Linux.</td><td>Names the packages, such as <code>libasound2-dev</code> and <code>pkg-config</code>, since installing them needs your system&#39;s package manager and your password.</td></tr><tr><td>Rust</td><td>The language llamatron is written in, with its build tool, cargo.</td><td>Offers to install it with rustup, the Rust project&#39;s own installer.</td></tr></tbody></table><p>rustup installs Rust into two folders in your home folder, <code>~/.cargo</code> and <code>~/.rustup</code>. It needs no password and touches nothing else, and <code>rustup self uninstall</code> removes it again.</p><p>On an Apple Silicon Mac, the script checks that Rust builds Apple Silicon programs. A Rust installed for Intel Macs builds a program that runs slowly under Rosetta; the script says how to switch it:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rustup set default-host aarch64-apple-darwin</span></span>
<span class="line"><span>rustup toolchain install stable</span></span></code></pre></div><h2 id="what-building-makes" tabindex="-1">What Building Makes <a class="header-anchor" href="#what-building-makes" aria-label="Permalink to &quot;What Building Makes&quot;">​</a></h2><p>The script builds the code in <code>src/</code> into <code>src/target/release/llamatron</code>, which <code>./llamatron.sh</code> runs. The first build downloads llamatron&#39;s libraries and takes a few minutes; running the script again rebuilds only what changed, in seconds. The <code>src/target/</code> folder holds everything the build makes and is never committed.</p><h2 id="logs" tabindex="-1">Logs <a class="header-anchor" href="#logs" aria-label="Permalink to &quot;Logs&quot;">​</a></h2><p>llamatron&#39;s sound engine writes what it did when it started and stopped, and any problem it met, to small files in <code>~/.llamatron/</code>, keeping the newest few. They never hold the music. If the sound stops or will not start, the newest file there says why.</p><h2 id="problems" tabindex="-1">Problems <a class="header-anchor" href="#problems" aria-label="Permalink to &quot;Problems&quot;">​</a></h2><table tabindex="0"><thead><tr><th>What happens</th><th>What to do</th></tr></thead><tbody><tr><td>The script says Rust builds Intel programs.</td><td>Run the two <code>rustup</code> commands above, then the script again.</td></tr><tr><td><code>linker &#39;cc&#39; not found</code></td><td>Apple&#39;s command line tools (Mac) or your system&#39;s compiler are missing: run the script again and say yes, or install <code>build-essential</code> on Linux.</td></tr><tr><td><code>alsa</code> not found on Linux</td><td>Install your system&#39;s ALSA development package and <code>pkg-config</code>.</td></tr><tr><td><code>./llamatron.sh</code> says llamatron is not built.</td><td>Run <code>sh build.sh</code>.</td></tr></tbody></table><p><a href="./BACKEND">Backend</a> explains how llamatron&#39;s sound engine works inside, for anyone changing it.</p>`,17)])])}const m=e(o,[["render",i]]);export{u as __pageData,m as default};
